def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    me = [h[0] for h in history]
    op = [h[1] for h in history]

    opp_c = sum(1 for x in op if x == 'C')
    my_c = sum(1 for x in me if x == 'C')

    if n >= 99:
        return 'D'

    if opp_c == 0:
        if my_c == 0:
            return 'C'
        if my_c == 1:
            return 'C'
        if my_c == 2:
            run_d = 0
            for x in reversed(op):
                if x == 'D':
                    run_d += 1
                else:
                    break
            if run_d >= 3:
                return 'C'
            return 'D'
        return 'D'

    last_op = op[-1]
    last_me = me[-1]

    if last_op == 'D':
        if last_me == 'D':
            run_d = 0
            for x in reversed(op):
                if x == 'D':
                    run_d += 1
                else:
                    break
            if run_d >= 2:
                return 'C'
            return 'D'
        else:
            return 'D'
    else:
        if last_me == 'D':
            return 'C'
        return 'C'
